insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_dance4_v1'
from (values
('117.309.c.1.A',3,'A senior reflects on a recital and critiques how well she sensed her position relative to partners during a fast traveling phrase. She is evaluating what?','["Her kinesthetic and spatial awareness", "The program order", "The costume budget", "The box office"]'::jsonb,0,'She assesses body sense and spacing.','original'),
('117.309.c.1.A',3,'A choreographer reviews rehearsal footage to evaluate whether the ensemble maintained clear formations. What is she evaluating?','["Costume color", "Spatial awareness in a group", "Music licensing", "Ticket totals"]'::jsonb,1,'Formations depend on spatial awareness.','original'),
('117.309.c.1.B',3,'A student prepares a plan that covers injury prevention, hydration, nutrition and recovery for a long rehearsal season. This shows what?','["A ticket policy", "A staging diagram", "A working knowledge of health, safety and wellness for dancers", "A costume list"]'::jsonb,2,'A season plan addresses dancer wellness.','original'),
('117.309.c.1.B',3,'Which practice best prevents overuse injuries during a heavy rehearsal schedule?','["Ignoring early pain signals", "Skipping warm-ups", "Dancing at full intensity every day", "Alternating intense days with lighter or rest days"]'::jsonb,3,'Rest allows recovery.','original'),
('117.309.c.1.C',3,'A dancer demonstrates a jazz combination, then evaluates her own technique against the genre''s standards. This shows what?','["A working knowledge of dance genre, style and vocabulary", "A budget review", "A lighting plot", "A stage cue"]'::jsonb,0,'She applies and evaluates genre knowledge.','original'),
('117.309.c.1.C',3,'Which evaluation of technique is most useful for a dancer working on a contemporary phrase?','["Comments about the poster", "Comments tied to release, weight and spiraling movement", "Comments about ticket prices", "Comments about the lobby"]'::jsonb,1,'Technical language fits the style.','original'),
('117.309.c.1.D',3,'A student sketches a floor pattern that echoes the ripples of water and then builds it into a group design. She is doing what?','["Selling tickets", "Writing a review", "Creating designs and images from the natural environment", "Repairing a floor"]'::jsonb,2,'Designs can come from nature.','original'),
('117.309.c.1.D',3,'A choreographer bases a formation on the skyline of a city. This is a design drawn from what?','["A natural environment only", "A weather report", "A sports score", "A constructed environment"]'::jsonb,3,'A skyline is built environment.','original'),
('117.309.c.2.A',3,'A student improvises a short study on a given theme, then creates three variations using different tempos and levels. What is she doing?','["Creating and improvising dance studies using theme and variation", "Designing costumes", "Memorizing a script", "Reviewing a play"]'::jsonb,0,'This is improvisation and variation.','original'),
('117.309.c.2.A',3,'What distinguishes a variation from the original theme?','["It copies the theme exactly", "It keeps the idea recognizable while changing some elements", "It removes all movement", "It has nothing in common with the theme"]'::jsonb,1,'A variation transforms but retains the theme.','original'),
('117.309.c.2.B',3,'After improvising, a student refines her ideas into a repeatable study and then critiques its structure. She is doing what?','["Copying a piece", "Avoiding feedback", "Improvising, constructing and evaluating original movement studies", "Dropping the work"]'::jsonb,2,'The process moves from improvising to constructing to evaluating.','original'),
('117.309.c.2.B',3,'Which step turns an improvisation into a constructed study?','["Performing it randomly", "Changing the music every time", "Forgetting the movement", "Selecting, ordering and setting the movements"]'::jsonb,3,'Constructing sets the material.','original'),
('117.309.c.2.C',3,'A choreographer asks viewers whether the sharp, staccato phrases effectively expressed anxiety. She is doing what?','["Evaluating the expression of ideas and emotions through movement", "Ordering costumes", "Selling programs", "Printing posters"]'::jsonb,0,'She checks whether movement communicates emotion.','original'),
('117.309.c.2.C',3,'Which feedback evaluates expression rather than technique?','["Your leg height was perfect", "The sudden stillness made the loss feel heartbreaking", "The music ran four minutes", "The turn count was five"]'::jsonb,1,'Expression concerns meaning and feeling.','original'),
('117.309.c.2.D',3,'A choreographer designs a work with advanced devices such as fragmentation, layering and motif development. What is she designing?','["A program note", "A set only", "Compositional forms using advanced elements", "A costume rack"]'::jsonb,2,'These are advanced choreographic tools.','original'),
('117.309.c.2.D',3,'What does motif development mean in choreography?','["Removing all repetition", "Using only one pose", "Skipping structure", "Repeating and transforming a key movement idea throughout the dance"]'::jsonb,3,'Motifs are developed through variation.','original'),
('117.309.c.3.A',3,'A dancer assesses her own performance of a complex sequence by watching a recording and checking counts against the music. What is she assessing?','["Rhythmic accuracy in memorized complex sequences", "Costume fabric", "Lobby setup", "Ticket revenue"]'::jsonb,0,'She measures timing accuracy.','original'),
('117.309.c.3.A',3,'Which method best checks accuracy in a memorized sequence?','["Guessing from memory", "Comparing performance to the counts and music in video playback", "Ignoring the recording", "Skipping practice"]'::jsonb,1,'Playback gives objective feedback.','original'),
('117.309.c.3.B',3,'A dancer phrases a movement so it breathes with the music, accenting some notes and releasing others. She is showing what?','["Lack of rehearsal", "Stage fright", "A refined sense of musicality and expressiveness", "A costume change"]'::jsonb,2,'Musicality shapes phrasing.','original'),
('117.309.c.3.B',3,'A wide range of dynamics in a dance includes what?','["Movement at only one speed", "Only stillness", "Movement with no energy", "Movement that varies from soft and sustained to sharp and explosive"]'::jsonb,3,'Range of dynamics is variety in force.','original'),
('117.309.c.3.C',3,'After a performance, a peer comments that a dancer''s focus carried to the back of the house and her commitment never wavered. The peer is evaluating what?','["Projection, confidence and expression", "Lobby lighting", "Seat comfort", "Ticket price"]'::jsonb,0,'These qualities show in performance.','original'),
('117.309.c.3.C',3,'Which observation evaluates projection?','["The curtain was red", "The dancer''s energy and focus reached beyond the stage edge", "The floor was clean", "The costume was blue"]'::jsonb,1,'Projection extends energy outward.','original'),
('117.309.c.3.D',3,'A senior designs a warm-up for her ensemble that moves from gentle joint mobility to dynamic leg swings to light jumps. She is doing what?','["Writing a script", "Planning a bus trip", "Designing an effective warm-up", "Printing a program"]'::jsonb,2,'A warm-up progresses in intensity.','original'),
('117.309.c.3.D',3,'What should a designed cool-down accomplish?','["Start a new routine", "Increase intensity", "Prevent rest", "Gradually lower heart rate and ease muscle tension"]'::jsonb,3,'Cool-downs support recovery.','original'),
('117.309.c.4.A',3,'A student evaluates the choreography of a classical Indian dance and a Western ballet, discussing how each tells a story. She is evaluating what?','["Choreography in dances from various cultures", "Seat maps", "Parking rules", "Costume prices"]'::jsonb,0,'Evaluation compares choreographic storytelling.','original'),
('117.309.c.4.A',3,'Which criterion would help evaluate choreography from a different historical period?','["The color of the stage", "How the movement reflects the values and style of the era", "The ticket price", "The seat numbers"]'::jsonb,1,'Historical context shapes style.','original'),
('117.309.c.4.B',3,'A student creates a multimedia presentation with video clips and timelines illustrating how a dance form evolved. She is using technology to do what?','["Avoid research", "Skip the history", "Illustrate understanding of significant dance forms and figures", "Hide the topic"]'::jsonb,2,'Technology supports presenting dance history.','original'),
('117.309.c.4.B',3,'Which item would strengthen a digital project on a major choreographer?','["A guess about her life", "Unverified rumors", "Random images", "Cited video excerpts and a timeline of her innovations"]'::jsonb,3,'Credible evidence supports the project.','original'),
('117.309.c.4.C',3,'A dancer improvises a solo to accompany a spoken-word poem and then sets it for a performance. She is working in what context?','["Dance in other content areas", "A single studio only", "A ticket office", "A math test"]'::jsonb,0,'Dance can combine with literature.','original'),
('117.309.c.4.C',3,'Constructing a dance for a documentary film requires considering what?','["Only the lobby", "How movement and camera framing work together", "Only the program cover", "Only the seating chart"]'::jsonb,1,'Media shape choreography choices.','original'),
('117.309.c.4.D',3,'A student studies archival video of a traditional ceremony dance and writes an evaluation of how it preserves cultural values. She is using what?','["No sources", "A guess", "Technology to evaluate historical and cultural dance forms", "A rumor"]'::jsonb,2,'Archives support evaluation.','original'),
('117.309.c.4.D',3,'When using online sources to evaluate a cultural dance, a student should do what?','["Accept any post", "Copy without credit", "Ignore the culture", "Check that the source is credible and respectful of the culture"]'::jsonb,3,'Credibility and respect matter.','original'),
('117.309.c.5.A',3,'A choreographer asks classmates to critique her new composition using specific criteria. She is doing what?','["Evaluating personal dance compositions and the work of others", "Skipping rehearsal", "Hiding her work", "Avoiding feedback"]'::jsonb,0,'Critique uses criteria.','original'),
('117.309.c.5.A',3,'Which statement is a useful evaluation of a composition?','["It was fine", "The shift from unison to canon clarified the climax, though the ending felt rushed", "I do not know", "Whatever"]'::jsonb,1,'Specific, balanced feedback is useful.','original'),
('117.309.c.5.B',3,'A student adapts a studio dance for a rooftop, changing spacing for the wind and sightlines. She is doing what?','["Cancelling the piece", "Repeating it unchanged", "Reconstructing a choreographic study for a new environment", "Ignoring the space"]'::jsonb,2,'Reconstruction adjusts to the setting.','original'),
('117.309.c.5.B',3,'Why must choreography be adapted when moved from a stage to a film?','["Nothing changes", "Cameras remove dancers", "Films have no movement", "The camera frames the movement and changes what the viewer sees"]'::jsonb,3,'Camera angles alter perception.','original'),
('117.309.c.5.C',3,'A senior assembles video of her best choreography, program notes and a research essay on a dance form. This is a what?','["Dance portfolio", "Costume list", "Lighting grid", "Ticket log"]'::jsonb,0,'A portfolio gathers artistic works and research.','original'),
('117.309.c.5.C',3,'Which belongs in a dance portfolio?','["Receipts", "Recordings of performances, reflections and research", "Random photos", "Bus schedules"]'::jsonb,1,'A portfolio documents growth.','original'),
('117.309.c.5.D',3,'After performing a choreographic study in a gallery, a dancer collects audience feedback and reflects on how the space changed the work. She is doing what?','["Ignoring the venue", "Deleting the video", "Performing and evaluating a choreographic study in a varied environment", "Avoiding reflection"]'::jsonb,2,'Evaluation follows performance in the setting.','original'),
('117.309.c.5.D',3,'Performing the same study on a stage and in a gym would reveal what?','["Nothing at all", "The weather", "The ticket price", "How the environment affects the choreography"]'::jsonb,3,'Space influences choices.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
